import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.nio.file.*;
import java.util.List;
import java.util.logging.Logger;

public class MessageProcessor {
    private static final Logger LOG = Logger.getLogger(MessageProcessor.class.getName());
    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String OUTPUT_BASE_DIR = "/var/spool/processor/output";
    private final SqsClient sqsClient;

    public MessageProcessor() {
        this.sqsClient = SqsClient.builder().build();
    }

    public void pollAndProcess() {
        while (true) {
            ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .messageAttributeNames("All")
                .build();

            List<Message> messages = sqsClient.receiveMessage(request).messages();
            for (Message msg : messages) {
                try {
                    processMessage(msg);
                    deleteMessage(msg);
                } catch (Exception e) {
                    LOG.warning("Failed to process message: " + e.getMessage());
                }
            }
        }
    }

    private void processMessage(Message message) throws IOException {
        String body = message.body();
        // Message format: JSON with "filename" and "content" fields
        String filename = extractField(body, "filename");
        String content = extractField(body, "content");
        String action = extractField(body, "action");

        if (filename == null || content == null) {
            throw new IllegalArgumentException("Missing required fields");
        }

        // Construct output path - filename comes directly from message
        Path outputPath = Paths.get(OUTPUT_BASE_DIR, filename);

        // Create parent directories if needed
        Files.createDirectories(outputPath.getParent());

        // Write content to file at the resolved path
        // NOTE: No symlink resolution check - path traversal possible via symlinks
        Files.writeString(outputPath, content, 
            StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);

        LOG.info("Wrote output to: " + outputPath.toAbsolutePath());

        // Post-processing: if action is "execute", run the file
        if ("execute".equals(action)) {
            executePostProcessor(outputPath);
        }
    }

    private void executePostProcessor(Path scriptPath) throws IOException {
        ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", 
            "chmod +x " + scriptPath.toString() + " && " + scriptPath.toString());
        pb.directory(new File(OUTPUT_BASE_DIR));
        pb.redirectErrorStream(true);
        Process process = pb.start();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                LOG.info("Script output: " + line);
            }
        }
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
            .queueUrl(QUEUE_URL)
            .receiptHandle(message.receiptHandle())
            .build());
    }

    private String extractField(String json, String field) {
        // Simple JSON field extraction (production would use Jackson)
        String pattern = "\"" + field + "\"\\s*:\\s*\"([^\"]+)\"";
        java.util.regex.Matcher m = java.util.regex.Pattern.compile(pattern).matcher(json);
        return m.find() ? m.group(1) : null;
    }

    public static void main(String[] args) {
        MessageProcessor processor = new MessageProcessor();
        LOG.info("Starting SQS message processor...");
        processor.pollAndProcess();
    }
}
